<script>
const COUNTRY_NAMES=<?php echo json_encode($countries,JSON_UNESCAPED_UNICODE); ?>,TXT=<?php echo json_encode(['movements'=>t('statistics_movements'),'flights'=>t('statistics_flights'),'pilots'=>t('statistics_pilots'),'airports'=>t('statistics_airports'),'landings'=>t('statistics_landings'),'live'=>t('statistics_view_live'),'empty'=>t('statistics_empty')],JSON_UNESCAPED_UNICODE); ?>;
const ownUserId=<?php echo $ownUserId; ?>;let mode=<?php echo json_encode($mode); ?>,userId=<?php echo $userId; ?>,searchTimer;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function metric(v,sort){if(sort==='distance')return Number(v.distance_nm||0).toLocaleString()+' NM';if(sort==='hours')return (Number(v.duration_seconds||0)/3600).toLocaleString(undefined,{maximumFractionDigits:1})+' h';if(sort==='airports')return Number(v.airports||0)+' '+TXT.airports;if(sort==='landings')return Number(v.landings||0)+' '+TXT.landings;return Number(v.flights||0)+' '+TXT.flights}
function empty(){return `<p>${esc(TXT.empty)}</p>`}function flag(code){return code&&code!=='--'?`<img class="flag" src="images/flags/${esc(code.toLowerCase())}.png" alt="">`:''}
function loadStatistics(){if(mode==='player'&&!userId){document.getElementById('statisticsContent').hidden=true;document.getElementById('statisticsLoading').hidden=false;document.getElementById('statisticsLoading').textContent=<?php echo json_encode(t('statistics_select_player')); ?>;return}const days=document.getElementById('period').value,aSort=document.getElementById('aircraftSort').value,pSort=document.getElementById('pilotSort').value,atcOrder=document.getElementById('atcSort').value;document.getElementById('statisticsLoading').hidden=false;document.getElementById('statisticsLoading').textContent=<?php echo json_encode(t('statistics_loading')); ?>;fetch(`execute/network_statistics.php?days=${days}&user_id=${mode==='global'?0:userId}&aircraft_sort=${aSort}&pilot_sort=${pSort}&atc_sort=${atcOrder}`).then(r=>r.json()).then(data=>{if(!data.success)throw new Error();const s=data.summary||{};sumFlights.textContent=s.flights||0;sumPilots.textContent=mode==='global'?(s.pilots||0):'1';sumDistance.textContent=Number(s.distance_nm||0).toLocaleString()+' NM';sumHours.textContent=(Number(s.duration_seconds||0)/3600).toLocaleString(undefined,{maximumFractionDigits:1})+' h';if(data.user)selectedPlayer.textContent=(data.user.real_name?data.user.real_name+' · ':'')+data.user.username;
const aircraft=data.top_aircraft||[];topAircraft.innerHTML=aircraft.length?aircraft.map((a,i)=>`<div class="rank"><span class="number">${i+1}</span><div><strong>${esc(a.code)}</strong><div class="meta">${a.flights} ${esc(TXT.flights)} · ${Number(a.distance_nm).toLocaleString()} NM · ${(Number(a.duration_seconds)/3600).toLocaleString(undefined,{maximumFractionDigits:1})} h · ${a.airports} ${esc(TXT.airports)}</div></div><strong>${esc(metric(a,aSort))}</strong></div>`).join(''):empty();
const airports=data.top_airports||[];topAirports.innerHTML=airports.length?airports.map((a,i)=>`<div class="rank"><span class="number">${i+1}</span><div><a class="pilot-name" href="airport.php?icao=${encodeURIComponent(a.code)}">${esc(a.code)}</a><div class="meta">${esc(a.name||'')} ${esc(a.municipality||'')}</div></div><strong>${a.movements} ${esc(TXT.movements)}</strong></div>`).join(''):empty();
const countries=data.top_movement_countries||[];topCountries.innerHTML=countries.length?countries.map((c,i)=>{const countryAirports=Array.isArray(c.airport_details)?c.airport_details:[],details=countryAirports.length?`<div class="country-airports">${countryAirports.map((a,j)=>`<div class="country-airport"><span class="number">${j+1}</span><div><a class="pilot-name" href="airport.php?icao=${encodeURIComponent(a.code)}">${esc(a.code)}</a><div class="meta">${esc(a.name||'')}${a.name&&a.municipality?' · ':''}${esc(a.municipality||'')}</div></div><strong>${Number(a.movements||0).toLocaleString()} ${esc(TXT.movements)}</strong></div>`).join('')}</div>`:'';return `<details class="country-details"><summary><div class="rank"><span class="number">${i+1}</span><div><strong>${flag(c.code)}${esc(COUNTRY_NAMES[c.code]||c.code)}</strong><div class="meta">${c.airports} ${esc(TXT.airports)}</div></div><strong>${c.movements} ${esc(TXT.movements)}</strong></div></summary>${details}</details>`}).join(''):empty();
const pilots=data.top_pilots||[];topPilots.innerHTML=pilots.length?pilots.map((p,i)=>{const name=p.real_name?`${p.real_name} (${p.username})`:p.username,live=p.online?`<span class="online-dot-small"></span> <a class="live-link" href="map.php?pilot_id=${p.user_id}&follow=1">${esc(TXT.live)}</a>`:'';return `<div class="rank"><span class="number">${i+1}</span><div>${flag(p.country_code)}<a class="pilot-name" href="profile.php?id=${p.user_id}">${esc(name)}</a><div class="meta">${p.flights} ${esc(TXT.flights)} · ${Number(p.distance_nm).toLocaleString()} NM · ${(Number(p.duration_seconds)/3600).toLocaleString(undefined,{maximumFractionDigits:1})} h ${live}</div></div><strong>${esc(metric(p,pSort))}</strong></div>`}).join(''):empty();renderAtc(data);pilotCard.hidden=mode!=='global';heatmapLink.hidden=mode!=='global';statisticsLoading.hidden=true;statisticsContent.hidden=false;history.replaceState(null,'',`statistics.php?mode=${mode}&days=${days}${mode==='player'?'&user_id='+userId:''}${location.hash}`)}).catch(()=>statisticsLoading.textContent='Server error')}
document.querySelectorAll('.mode-button').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('.mode-button').forEach(x=>x.classList.toggle('active',x===b));playerPicker.hidden=mode!=='player';if(mode==='global')userId=0;else if(mode==='own')userId=ownUserId;else{userId=0;selectedPlayer.textContent=''}loadStatistics()});period.onchange=loadStatistics;aircraftSort.onchange=loadStatistics;pilotSort.onchange=loadStatistics;atcSort.onchange=loadStatistics;
playerSearch.oninput=()=>{clearTimeout(searchTimer);const q=playerSearch.value.trim();if(q.length<2){playerResults.innerHTML='';return}searchTimer=setTimeout(()=>fetch('execute/statistics_player_search.php?q='+encodeURIComponent(q)).then(r=>r.json()).then(d=>{playerResults.innerHTML=(d.players||[]).map(p=>`<button class="search-result" data-id="${p.id}" data-name="${esc(p.real_name||p.username)}">${flag(p.country_code)}${esc(p.real_name||p.username)} · ${esc(p.username)}</button>`).join('');playerResults.querySelectorAll('button').forEach(b=>b.onclick=()=>{userId=Number(b.dataset.id);selectedPlayer.textContent=b.dataset.name;playerSearch.value='';playerResults.innerHTML='';loadStatistics()})}),250)};
function renderAtc(data){const summary=data.atc_summary||{},positions=data.top_atc_positions||[],controllers=data.top_controllers||[],sort=atcSort.value;sumAtcSessions.textContent=Number(summary.sessions||0).toLocaleString();sumAtcHours.textContent=(Number(summary.duration_seconds||0)/3600).toLocaleString(undefined,{maximumFractionDigits:1})+' h';sumAtcControllers.textContent=Number(summary.controllers||0).toLocaleString();sumAtcPositions.textContent=Number(summary.positions||0).toLocaleString();sumAtcStations.textContent=Number(summary.stations||0).toLocaleString();avgAtcSession.textContent=(Number(summary.average_duration_seconds||0)/3600).toLocaleString(undefined,{maximumFractionDigits:1})+' h';const atcMetric=p=>sort==='sessions'?`${Number(p.sessions||0).toLocaleString()} <?php echo addslashes(t('statistics_atc_sessions')); ?>`:sort==='average'?`Ø ${(Number(p.average_duration_seconds||0)/3600).toLocaleString(undefined,{maximumFractionDigits:1})} h`:`${(Number(p.duration_seconds||0)/3600).toLocaleString(undefined,{maximumFractionDigits:1})} h`;const atcMeta=p=>`${Number(p.sessions||0).toLocaleString()} <?php echo addslashes(t('statistics_atc_sessions')); ?> · ${(Number(p.duration_seconds||0)/3600).toLocaleString(undefined,{maximumFractionDigits:1})} h · Ø ${(Number(p.average_duration_seconds||0)/3600).toLocaleString(undefined,{maximumFractionDigits:1})} h`;topAtcPositions.innerHTML=positions.length?positions.map((p,i)=>`<div class="rank"><span class="number">${i+1}</span><div><strong>${esc(p.callsign)}</strong><div class="meta">${atcMeta(p)}</div></div><strong>${atcMetric(p)}</strong></div>`).join(''):empty();topControllers.innerHTML=controllers.length?controllers.map((p,i)=>`<div class="rank"><span class="number">${i+1}</span><div>${flag(p.country_code)}<a class="pilot-name" href="profile.php?id=${p.user_id}">${esc(p.real_name||p.username)}</a><div class="meta">${atcMeta(p)}</div></div><strong>${atcMetric(p)}</strong></div>`).join(''):empty();topControllersWrap.hidden=mode!=='global'}
loadStatistics();if(location.hash==='#aircraftStatistics')setTimeout(()=>document.getElementById('aircraftStatistics').scrollIntoView({behavior:'smooth'}),250);
</script></body></html>
